package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.util.regex.*;
public class NativeProgressLocateWiringTest {
 private String source(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n+".java"));}
 @Test public void scopeIsIndependentAndBounded(){assertEquals(3,RootProgressLocateScope.MAX_FRAMES);assertEquals(2,RootProgressLocateScope.MAX_SWIPES);assertEquals(15,RootProgressLocateScope.SOURCE_TASK_ID);assertNotEquals(RootProgressScanScope.DIRECTORY,RootProgressLocateScope.DIRECTORY);assertNotEquals(ReadOnlyCheckpoint.CURRENT.directory(),RootProgressLocateScope.DIRECTORY);assertTrue(RootProgressLocateScope.validIndex(3));assertFalse(RootProgressLocateScope.validIndex(4));}
 @Test public void absoluteWindowAndAdmissionCannotRenew(){long t=RootProgressLocateScope.STARTS_UTC;assertTrue(RootProgressLocateScope.current(t));assertFalse(RootProgressLocateScope.current(t-1));assertFalse(RootProgressLocateScope.current(RootProgressLocateScope.EXPIRES_UTC));assertFalse(RootProgressLocateScope.admissionCurrent(RootProgressLocateScope.EXPIRES_UTC-RootProgressLocateScope.SESSION_TTL));assertEquals(91000,RootProgressLocateScope.deadline(1000,t,181000));assertEquals(2000,RootProgressLocateScope.deadline(1000,t,2000));}
 @Test public void allOldLiveStartsAreBlocked()throws Exception{Matcher m=Pattern.compile("(?m)^    static CaptureSessionRuntime (start\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(source("CaptureSessionRuntime"));int n=0;while(m.find()){if(m.group(1).equals("startProgressLocate")||m.group(1).equals("startCheckpointRead"))continue;assertTrue(m.group(1),m.group(2).contains("if(RootProgressLocateScope.ACTIVE)throw"));n++;}assertTrue(n>=16);}
 @Test public void allOldLiveIssuersAreBlocked()throws Exception{Matcher m=Pattern.compile("static [\\w.<>]+ (issue\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(source("VisibleCaptureAuthority"));int n=0;while(m.find()){if(m.group(1).equals("issueProgressLocateIntent")||m.group(1).equals("issueProgressLocateFrame")||m.group(1).equals("issueCheckpointIntent")||m.group(1).equals("issueCheckpointFrame"))continue;assertTrue(m.group(1),m.group(2).contains("if(RootProgressLocateScope.ACTIVE)throw"));n++;}assertTrue(n>=21);}
 @Test public void layoutRoutesAreDiagnosticAndFinalGated()throws Exception{String r=source("CaptureSessionRuntime"),i=source("RootReturnReadIntent");assertTrue(i.contains("boolean layoutDiagnostic(){return checkpoint!=null||progressLocate;}"));assertTrue(r.contains("if(returnReadIntent.layoutDiagnostic())pendingProgressPublication="));assertTrue(r.contains("returnReadIntent.layoutDiagnostic()?audit.compactSummary():audit.summary()"));assertTrue(r.contains("if(!returnReadIntent.layoutDiagnostic()&&readOnlyObservation"));assertTrue(r.contains("returnReadIntent.layoutDiagnostic()?ReadOnlyTwoStageRun.Capture.layoutDiagnostic("));assertTrue(source("DormantCaptureConfirmationActivity").contains("returnReadReports.add(exact.finalizeProgressPublication(details))"));}
 @Test public void exactCluesAndSafetyStopBeforeAnyNavigation()throws Exception{String r=source("CaptureSessionRuntime");int a=r.indexOf("layout.locateRowsUsable()"),b=r.indexOf("layout.locateSafetyStop()"),c=r.indexOf("layout.locateStopClue()"),d=r.indexOf("claimScroll(returnReadIndex");assertTrue(a>0&&a<b&&b<c&&c<d);assertTrue(r.contains("var progress=readOnlyObservation"));assertTrue(r.contains("if(progress.scanClue())"));}
 @Test public void fixedDownDirectionAndSeparateBurnPrecedeDispatch()throws Exception{String r=source("CaptureSessionRuntime");assertTrue(r.contains("ReviewShizukuSwipeActor.forProgressLocate("));assertTrue(r.contains("ReviewShizukuSwipeActor.Direction.DOWN"));assertTrue(r.contains("RootProgressLocateScope.burnScroll("));assertTrue(r.contains("exact!=target||!rootPreflightFresh()||!permit.burn("));assertTrue(r.contains("scanFreshSource(metadata)&&permit.current(requestOwner,SystemClock.elapsedRealtime())&&rootPreflightFresh()"));assertTrue(r.contains("scanNavigation()&&rootLower<=returnReadIntent.scanBoundary()"));}
 @Test public void durableSlotsCannotReset()throws Exception{String s=source("RootProgressLocateScope");assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("fixedDownward=true"));assertTrue(s.contains("c.force(true)"));assertFalse(s.contains("TRUNCATE_EXISTING"));assertFalse(s.contains("delete("));}
 @Test public void newChoicePrecedesFrozenCheckpoint()throws Exception{String a=source("DormantCaptureConfirmationActivity");String c=a.substring(a.indexOf("private void showCaptureChoices()"));assertTrue(c.indexOf("RootProgressLocateScope.ACTIVE")<c.indexOf("ReadOnlyCheckpoint.CURRENT!=null"));assertTrue(c.contains("RootProgressLocateScope.admissionCurrent"));assertTrue(source("RootCaptureUi").contains("批准上方内容定位：最多2次向下滑动"));}
 @Test public void actualNavigationIsReportedWithoutBusinessAuthority()throws Exception{String r=source("CaptureSessionRuntime");assertTrue(r.contains("BOUNDED_DOWN_V42"));assertTrue(r.contains("returnReadIntent.scanSummary()"));assertTrue(r.contains("businessActionAuthority=false taskTaps=0 back=0 textEntry=0"));String i=source("RootReturnReadIntent");assertTrue(i.contains("swipeInvocations="));assertTrue(i.contains("swipeConfirmedExits="));assertTrue(i.contains("scrollSlotsConsumed="));}
}
